
.xianxia-card {
  width: 100%;
  max-width: 800px;
  background: linear-gradient(135deg, var(--c-scroll-beige) 0%, var(--c-cloud-white) 100%);
  border: 2px solid var(--c-border-brown);
  box-shadow:
    0 4px 20px rgba(26, 26, 46, 0.15),
    inset 0 0 30px rgba(212, 175, 55, 0.05);
  display: flex;
  flex-direction: column;
  font-family: var(--font-xianxia);
  color: var(--c-ink-black);
  font-size: 14px;
  line-height: 1.5;
  margin: 0 auto;
  position: relative;

  /* 古风边角装饰 */
  &::before,
  &::after {
    content: '◆';
    position: absolute;
    color: var(--c-spirit-gold);
    font-size: 12px;
    opacity: 0.6;
  }

  &::before {
    top: 8px;
    left: 8px;
  }

  &::after {
    bottom: 8px;
    right: 8px;
  }
}

.content-area {
  padding: 12px 16px;
  min-height: 0;
}
