
.character-panel {
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.char-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-border-brown);
}

.char-name {
  font-size: 18px;
  font-weight: bold;
  color: var(--c-ink-black);
  letter-spacing: 3px;
}

.char-cultivation {
  font-size: 12px;
  color: var(--c-spirit-purple);
  background: rgba(128, 90, 213, 0.1);
  padding: 4px 10px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.cultivation-icon {
  font-size: 10px;
}

.section-label {
  font-size: 12px;
  color: var(--c-spirit-gold);
  margin-bottom: 6px;
  letter-spacing: 1px;
}

.status-section,
.mind-section,
.relation-section,
.cognition-section,
.physiology-section,
.arclight-section {
  margin-bottom: 14px;
}

.status-text {
  font-size: 13px;
  color: var(--c-jade-mist);
  line-height: 1.6;
  padding-left: 8px;
  border-left: 2px solid var(--c-border-brown);
}

.mind-text {
  font-size: 13px;
  color: var(--c-ink-black);
  font-style: italic;
  background: rgba(212, 175, 55, 0.08);
  padding: 10px 12px;
  border-radius: 6px;
  line-height: 1.5;
}

/* 献祭弧光 */
.arclight-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: bold;
  color: var(--c-mist-blue);
  background: rgba(66, 153, 225, 0.12);
  padding: 4px 12px;
  border-radius: 12px;
  border: 1px solid rgba(66, 153, 225, 0.3);
}

/* 关系 */
.relation-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 8px;
}

.relation-item {
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid var(--c-border-brown);
  border-radius: 4px;
  padding: 8px 10px;
}

.relation-name {
  display: block;
  font-size: 11px;
  color: var(--c-jade-mist);
  margin-bottom: 4px;
}

.relation-value {
  font-size: 12px;
  font-weight: bold;
  color: var(--c-ink-black);

  &.status {
    color: var(--c-mist-blue);
  }
}

.relation-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.relation-bar {
  flex: 1;
  height: 6px;
  background: rgba(0, 0, 0, 0.1);
  border-radius: 3px;
  overflow: hidden;
}

.relation-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;

  &.intimacy {
    background: linear-gradient(90deg, var(--c-jade-green), #48bb78);
  }

  &.immorality {
    background: linear-gradient(90deg, var(--c-spirit-purple), #9f7aea);
  }

  &.fertility {
    background: linear-gradient(90deg, var(--c-blood-red), #fc8181);
  }

  &.desire {
    background: linear-gradient(90deg, #e53e3e, var(--c-blood-red));
  }
}

.relation-num {
  font-size: 11px;
  font-weight: bold;
  color: var(--c-ink-black);
  min-width: 24px;
  text-align: right;
}

/* 认知 */
.cognition-grid {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.cognition-item {
  background: rgba(66, 153, 225, 0.1);
  border: 1px solid var(--c-mist-blue);
  border-radius: 4px;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.cognition-name {
  font-size: 11px;
  color: var(--c-jade-mist);
}

.cognition-value {
  font-size: 12px;
  font-weight: bold;
  color: var(--c-mist-blue);

  &.warn {
    color: var(--c-blood-red);
  }
}

/* 生理数值条 */
.physio-bars {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 10px;
}

.physio-bar-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.physio-bar-label {
  font-size: 11px;
  color: var(--c-jade-mist);
  min-width: 50px;
  flex-shrink: 0;
}

.physiology-text {
  font-size: 12px;
  color: var(--c-jade-mist);
  line-height: 1.5;
  padding: 8px 10px;
  background: rgba(197, 48, 48, 0.05);
  border: 1px solid rgba(197, 48, 48, 0.2);
  border-radius: 4px;
}

/* 服装 */
.attire-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.attire-item {
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid var(--c-border-brown);
  border-radius: 4px;
  padding: 6px 8px;
  font-size: 11px;
  flex: 1 1 auto;
  min-width: 120px;
  max-width: 100%;
}

.attire-slot {
  display: block;
  color: var(--c-spirit-purple);
  font-weight: bold;
  margin-bottom: 2px;
}

.attire-desc {
  color: var(--c-jade-mist);
  line-height: 1.4;
  display: block;
  word-break: break-all;
}

/* 身体状态 */
.body-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.body-item {
  padding: 6px 0;
  border-bottom: 1px dashed rgba(139, 115, 85, 0.15);

  &:last-child {
    border-bottom: none;
  }
}

.body-label {
  display: block;
  font-size: 11px;
  color: var(--c-spirit-purple);
  font-weight: bold;
  margin-bottom: 3px;
}

.body-value {
  display: block;
  font-size: 12px;
  color: var(--c-jade-mist);
  line-height: 1.5;
}

/* 子宫精液占比 */
.semen-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.semen-item {
  background: rgba(197, 48, 48, 0.06);
  border: 1px solid rgba(197, 48, 48, 0.15);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 11px;
  display: flex;
  gap: 6px;
  align-items: center;
}

.semen-name {
  color: var(--c-ink-black);
  font-weight: bold;
}

.semen-ratio {
  color: var(--c-blood-red);
}

@media (max-width: 500px) {
  .relation-grid {
    grid-template-columns: 1fr;
  }

  .char-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .attire-item {
    min-width: 100%;
  }
}
