
.heroine-panel {
  padding: 12px 16px;
  border-bottom: 2px solid var(--c-border-brown);
  background: linear-gradient(135deg, rgba(128, 90, 213, 0.05) 0%, transparent 100%);
}

.heroine-header {
  margin-bottom: 12px;
}

.heroine-name {
  font-size: 20px;
  font-weight: bold;
  color: var(--c-spirit-purple);
  letter-spacing: 4px;
  margin-bottom: 4px;
}

.heroine-status {
  font-size: 12px;
  color: var(--c-jade-mist);
  line-height: 1.4;
}

.section-title {
  font-size: 13px;
  color: var(--c-spirit-gold);
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.status-section,
.recent-act-section {
  margin-bottom: 12px;
}

.status-text {
  font-size: 13px;
  color: var(--c-jade-mist);
  line-height: 1.6;
  padding-left: 8px;
  border-left: 2px solid var(--c-border-brown);
}

.stats-row {
  display: flex;
  gap: 12px;
  margin-bottom: 12px;
}

.stat-item {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  font-size: 12px;
  color: var(--c-jade-mist);
  min-width: 50px;
}

.stat-bar {
  flex: 1;
  height: 8px;
  background: rgba(0, 0, 0, 0.1);
  border-radius: 4px;
  overflow: hidden;
}

.stat-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s ease;

  &.desire {
    background: linear-gradient(90deg, var(--c-blood-red), #e53e3e);
  }
}

.stat-value {
  font-size: 12px;
  font-weight: bold;
  color: var(--c-ink-black);
  min-width: 24px;
  text-align: right;
}

.attire-section {
  margin-bottom: 12px;
}

.attire-style {
  font-size: 11px;
  color: var(--c-spirit-purple);
  margin-bottom: 6px;
  font-style: italic;
}

.attire-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.attire-item {
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid var(--c-border-brown);
  border-radius: 4px;
  padding: 6px 8px;
  font-size: 11px;
  flex: 1 1 auto;
  min-width: 120px;
  max-width: 100%;
}

.attire-slot {
  display: block;
  color: var(--c-spirit-purple);
  font-weight: bold;
  margin-bottom: 2px;
}

.attire-desc {
  color: var(--c-jade-mist);
  line-height: 1.4;
  display: block;
  word-break: break-all;
}

.thought-bubble {
  background: rgba(212, 175, 55, 0.1);
  border: 1px dashed var(--c-spirit-gold);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-bottom: 10px;

  &.mind-bubble {
    background: rgba(128, 90, 213, 0.08);
    border-color: var(--c-spirit-purple);
  }
}

.thought-icon {
  font-size: 14px;
  flex-shrink: 0;
}

.thought-text {
  font-size: 12px;
  color: var(--c-ink-black);
  font-style: italic;
  line-height: 1.5;
}

/* 身体状态 */
.body-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.body-item {
  padding: 6px 0;
  border-bottom: 1px dashed rgba(139, 115, 85, 0.15);

  &:last-child {
    border-bottom: none;
  }
}

.body-label {
  display: block;
  font-size: 11px;
  color: var(--c-spirit-purple);
  font-weight: bold;
  margin-bottom: 3px;
}

.body-value {
  display: block;
  font-size: 12px;
  color: var(--c-jade-mist);
  line-height: 1.5;
}

.semen-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.semen-item {
  background: rgba(197, 48, 48, 0.06);
  border: 1px solid rgba(197, 48, 48, 0.15);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 11px;
  display: flex;
  gap: 6px;
  align-items: center;
}

.semen-name {
  color: var(--c-ink-black);
  font-weight: bold;
}

.semen-ratio {
  color: var(--c-blood-red);
}

@media (max-width: 500px) {
  .attire-item {
    min-width: 100%;
  }
}
